<?php
require_once __DIR__ . '/inc/mother_session.php';
require_once __DIR__ . '/inc/mcare_chat_intelligence.php';
$chatConversation=mcare_chat_open_conversation($db,$motherId,(int)$_SESSION['u_id'],$language);
$chatTurnsQuery=$db->prepare('SELECT speaker,original_text,structured_data FROM tbl_mcare_chat_turns WHERE conversation_id=? ORDER BY turn_id DESC LIMIT 100');
$chatTurnsQuery->execute([$chatConversation['id']]);$chatHistory=array_reverse($chatTurnsQuery->fetchAll(PDO::FETCH_ASSOC));
$page_title=$t('M-CARE maternal chatbot');include 'inc/links.php';include 'inc/header.php';
?>
<div class="inner-wrapper"><?php include 'inc/sidebar.php'; ?><section role="main" class="content-body"><?php include 'inc/inner-header.php'; ?>
<section class="panel"><header class="panel-heading"><h2 class="panel-title"><i class="fa fa-comments"></i> <?=$t('M-CARE maternal chatbot')?></h2></header><div class="panel-body">
<p class="text-muted"><?=$t('Messages matching an urgent warning sign are saved in an alert and shared with your assigned care team for review.')?></p>
<div id="mcare-bot-log" role="log" aria-live="polite" aria-relevant="additions text" style="height:360px;overflow-y:auto;border:1px solid #dce6e9;border-radius:8px;padding:14px;margin:12px 0;background:#f7fafb"></div>
<div id="mcare-bot-status" class="text-muted" role="status" aria-live="polite" style="min-height:20px"></div>
<form id="mcare-bot-form"><div class="form-group"><label for="mcare-bot-input"><?=$t('Your message')?></label><textarea id="mcare-bot-input" class="form-control" rows="3" maxlength="2000" required placeholder="<?=$t('Type your question in English or Kinyarwanda')?>"></textarea></div><button id="mcare-bot-send" type="submit" class="btn btn-primary"><i class="fa fa-paper-plane"></i> <?=$t('Send message')?></button> <button id="mcare-bot-clear" type="button" class="btn btn-default"><?=$t('Clear conversation')?></button> <a class="btn btn-info" href="mother_messages"><?=$t('Chat with your care team')?></a></form>
</div></section></section></div><?php include 'inc/footer.php';include 'inc/scripts.php'; ?>
<script>
(function(){
const log=document.getElementById('mcare-bot-log'),form=document.getElementById('mcare-bot-form'),input=document.getElementById('mcare-bot-input'),send=document.getElementById('mcare-bot-send'),status=document.getElementById('mcare-bot-status'),clear=document.getElementById('mcare-bot-clear');
const csrf=<?=json_encode($_SESSION['csrf_token'])?>,language=<?=json_encode($language)?>;
const history=<?=json_encode(array_map(static fn($turn)=>['speaker'=>$turn['speaker'],'text'=>$turn['original_text']],$chatHistory),JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_UNESCAPED_UNICODE)?>;
const labels={you:language==='rw'?'Wowe':'You',bot:'M-CARE',welcome:language==='rw'?'Muraho. Mumbaze ibibazo rusange ku gutwita, imirire, gusura ikigo nderabuzima cyangwa kwiyitaho nyuma yo kubyara.':'Hello. Ask me general questions about pregnancy, nutrition, ANC visits, or postpartum care.',sent:language==='rw'?'M-CARE irimo kugusubiza…':'M-CARE is preparing a response…',failure:language==='rw'?'Uyu mufasha ntashoboye gusubiza ubu. Ushobora kwandikira itsinda ry’ubuzima.':'The helper is unavailable right now. You can message your care team.',sources:language==='rw'?'Inkomoko:':'Sources:',now:language==='rw'?'Ubu':'Now',handoff:language==='rw'?'Vugana n’itsinda ry’ubuzima':'Chat with your care team'};
function bubble(name,message,side,sources,handoff){const row=document.createElement('div');row.style.marginBottom='12px';row.style.textAlign=side==='right'?'right':'left';const item=document.createElement('div');item.style.display='inline-block';item.style.textAlign='left';item.style.maxWidth='88%';item.style.padding='10px 13px';item.style.border='1px solid #dce6e9';item.style.borderRadius='12px';item.style.background=side==='right'?'#e6f3f5':'#fff';item.style.whiteSpace='pre-wrap';item.style.overflowWrap='anywhere';const heading=document.createElement('strong');heading.textContent=name;const body=document.createElement('div');body.textContent=message;const stamp=document.createElement('small');stamp.className='text-muted';stamp.textContent=labels.now;item.append(heading,body,stamp);if(sources&&sources.length){const sourceLine=document.createElement('small');sourceLine.className='text-muted';sourceLine.textContent='\n'+labels.sources+' '+sources.join(', ');item.append(sourceLine);}if(handoff){const link=document.createElement('a');link.href='mother_messages';link.className='btn btn-info btn-sm';link.style.marginTop='9px';link.textContent=labels.handoff;item.append(document.createElement('br'),link);}row.append(item);log.append(row);log.scrollTop=log.scrollHeight;}
if(history.length){history.forEach(turn=>bubble(turn.speaker==='mother'?labels.you:'M-CARE',turn.text,turn.speaker==='mother'?'right':'left'));}else bubble('M-CARE',labels.welcome,'left');
clear.addEventListener('click',async()=>{const p=new URLSearchParams();p.set('_csrf',csrf);p.set('reset_conversation','1');try{await fetch('mother_assistant',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded','Accept':'application/json'},body:p.toString()});}catch(error){}log.replaceChildren();bubble('M-CARE',labels.welcome,'left');status.textContent='';input.focus();});
form.addEventListener('submit',async e=>{e.preventDefault();const question=input.value.trim();if(!question||send.disabled)return;bubble(labels.you,question,'right');input.value='';send.disabled=true;status.textContent=labels.sent;try{const p=new URLSearchParams();p.set('_csrf',csrf);p.set('question',question);p.set('topic','education');const response=await fetch('mother_assistant',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded','Accept':'application/json'},body:p.toString()});const data=await response.json();if(!response.ok)throw new Error(data.error||labels.failure);bubble('M-CARE',data.reply,'left',data.sources||[],data.handoff===true);status.textContent='';}catch(error){bubble('M-CARE',error.message||labels.failure,'left');status.textContent='';}finally{send.disabled=false;input.focus();}});
})();
</script>
